'use strict';
process.env.LTS_FLOW_RELEASE||='v407';
const fs=require('node:fs'),assert=require('node:assert/strict'),crypto=require('node:crypto');
const {setup,open}=require('./lts_v382_browser.cjs'),{synthetic}=require('../fixtures/lts_v408_cipo.cjs'),{chromium,webkit}=require('playwright');
const fixture=require('./lts_v379_fixtures.cjs'),baseResponse=fixture.response;fixture.response=function(name,args){const j=baseResponse(name,args);return /^lts_browser_wealth_detail_/.test(name)?fixture.contracts(structuredClone(j)):j;};
const out='qa/v407-cipo';fs.mkdirSync(out,{recursive:true});const hash=x=>crypto.createHash('sha256').update(JSON.stringify(x)).digest('hex');
async function run(browser,engine,width,height=980){const h=await setup(browser,width,height,'2026-11-04T15:00:00Z');let f;try{
 f=await open(h,'v407',true);await f.waitForFunction(()=>window.__LTS_V408_CIPO?.installed);
 await f.locator('#nav [data-v="Patrimônio"]:visible,#dx1MobileNav [data-mobile-route="Patrimônio"]:visible').click();await f.waitForFunction(()=>__LTS_V168_STATE.wealth.data&&!__LTS_V168_STATE.wealth.loading);
 const evidence=synthetic();await f.evaluate(p=>{const s=__LTS_V168_STATE.wealth;s.data.financing.documentary.items[0].metadata.acquisition_documentary_bridge_v408=p;s.tab='assets';render();},evidence);
 const root=f.locator('[data-v408-cipo]'),details=root.locator(':scope>details');assert.equal(await root.count(),1);assert.equal(await details.getAttribute('open'),null);
 assert.match(await root.locator('.v408-material').innerText(),/Conferência de 04\/11\/2026: 43 lançamentos documentados.*5 lançamentos/);
 const before=hash(await f.evaluate(()=>__LTS_V168_STATE.wealth.data));const closed=await root.evaluate(e=>({height:e.getBoundingClientRect().height,width:innerWidth,scroll:document.documentElement.scrollWidth}));assert(closed.height<185,'closed source remains compact');assert(closed.scroll<=width+2);
 await details.locator(':scope>summary').click();assert.equal(await root.locator('.v408-group').count(),32);assert.equal(await root.locator('.v408-group[open]').count(),0);
 const first=root.locator('.v408-group').first();await first.locator(':scope>summary').click();assert.match(await first.innerText(),/A grade registra 30\/01\/2020/);assert.match(await first.innerText(),/Caixa · 31\/01\/2020/);assert.equal(await first.locator('.v408-origin[open]').count(),0);
 await first.locator('.v408-origin>summary').click();assert.match(await first.locator('.v408-origin').innerText(),/Pagamentos e Recebimentos.*2000/s);await first.locator('.v408-origin>summary').click();
 await root.locator('.v408-residuals>summary').click();assert.equal(await root.locator('.v408-residual').count(),5);const geom=await root.evaluate(e=>({width:innerWidth,scroll:document.documentElement.scrollWidth,values:[...e.querySelectorAll('b')].filter(x=>x.getClientRects().length).map(x=>{const r=x.getBoundingClientRect();return{left:r.left,right:r.right};})}));assert(geom.scroll<=width+2);assert(geom.values.every(x=>x.left>=0&&x.right<=width+2));await h.page.screenshot({path:out+'/'+engine+'-'+width+'-source.png'});
 assert.equal(hash(await f.evaluate(()=>__LTS_V168_STATE.wealth.data)),before,'opening evidence preserves received financial data');
 await f.evaluate(()=>{const docs=__LTS_V168_STATE.wealth.data.financing.documentary.items;docs.unshift({...docs[0],as_of_date:'2026-11-04',metadata:{}});render();render();});assert.equal(await root.count(),1);assert.equal(await details.getAttribute('open'),null,'historic evidence survives a newer statement without duplication');
 const retained=hash(await f.evaluate(()=>__LTS_V168_STATE.wealth.data));await f.evaluate(()=>render());assert.equal(hash(await f.evaluate(()=>__LTS_V168_STATE.wealth.data)),retained);
 await f.evaluate(()=>{const d=__LTS_V168_STATE.wealth.data.financing.documentary.items.find(x=>x.metadata?.acquisition_documentary_bridge_v408);d.metadata.acquisition_documentary_bridge_v408.groups[0].cash_rows[0].amount='60.01';render();});assert.match(await root.innerText(),/precisa ser conferida antes de ser exibida/);assert.equal(await root.locator('.v408-group').count(),0,'conflicting money is not rendered as a reconciled group');
 assert.deepEqual(h.errors,[]);assert.deepEqual(h.writes,[]);return{pass:true,engine,width,closed_height:closed.height,groups:32,documented_rows:43,residuals:5,date_discrepancies_visible:true,original_payload_unchanged:true,uncertain_composition_rejected:true,source_cutoff_visible:true,synthetic_only:true,private_session:false,physical_iphone:false};
}catch(error){await h.page.screenshot({path:out+'/'+engine+'-'+width+'-failure.png'}).catch(()=>{});fs.writeFileSync(out+'/'+engine+'-'+width+'-failure.json',JSON.stringify({error:error.stack,body:f?await f.locator('body').innerText():null},null,2));throw error;}finally{await h.ctx.close();}}
module.exports={run};
if(require.main===module)(async()=>{const results=[];for(const[engine,type]of[['chromium',chromium],['webkit',webkit]]){const browser=await type.launch();try{for(const width of[320,393,1366])results.push(await run(browser,engine,width));}finally{await browser.close();}}fs.writeFileSync(out+'/result.json',JSON.stringify({pass:true,results},null,2));console.log(JSON.stringify({pass:true,runs:results.length}));})().catch(e=>{console.error(e);process.exitCode=1});
